import com.diffplug.gradle.spotless.SpotlessExtension

plugins {
    `java-library`
}

apply(plugin = "com.diffplug.spotless")

java {

    disableAutoTargetJvm()

}

extensions.configure<SpotlessExtension> {

    java {

        endWithNewline()
        leadingTabsToSpaces(4)

        removeUnusedImports()

        trimTrailingWhitespace()
        // FlatBuffers output under protocol/schema is generated by flatc and never edited by hand.
        targetExclude("build/generated/**/*", "src/main/java/**/protocol/schema/**")

    }

    groovyGradle {

        endWithNewline()

        leadingTabsToSpaces(4)

        trimTrailingWhitespace()

    }

}